import sys
import logging
import unittest

from numpy import (
  array as np_array,
)

from resim.pvt.eos import (
  pr78,
)

from resim.pvt.env import (
  env2p,
)

from matplotlib import (
  pyplot as plt,
)


logger = logging.getLogger('env')
logger.setLevel(logging.INFO)
handler = logging.StreamHandler(sys.stdout)
formatter = logging.Formatter('%(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)


plotting = False


class env2pPT(unittest.TestCase):

  @staticmethod
  def plot(env, xmin, xmax, ymin, ymax):
    fig, ax = plt.subplots(1, 1, figsize=(6., 4.), tight_layout=True)
    ax.plot(env.T - 273.15, env.P / 1e6, lw=2., c='teal', zorder=2,
            label='Phase boundary')
    if env.Pc is not None:
      ax.plot(env.Tc - 273.15, env.Pc / 1e6, 'o', lw=0., c='r', zorder=2,
              label='Critical point')
    ax.set_xlim(xmin - 273.15, xmax - 273.15)
    ax.set_ylim(ymin / 1e6, ymax / 1e6)
    ax.set_xlabel('Temperature [C]')
    ax.set_ylabel('Pressure [MPa]')
    ax.legend(loc='best', fontsize=9)
    ax.grid(zorder=1)
    plt.show()
    pass

  def test_01(self):
    logger.info('\nTest #01.\nComponents: C1 C2 C3 NC4 C5+')
    yi = np_array([0.7167, 0.0895, 0.0917, 0.0448, 0.0573])
    Pci = np_array([45.99, 48.72, 42.48, 37.96, 23.975]) * 1e5
    Tci = np_array([190.56, 305.32, 369.83, 425.12, 551.022])
    mwi = np_array([16.043, 30.07, 44.097, 58.123, 120.0]) / 1e3
    wi = np_array([0.012, 0.1, 0.152, 0.2, 0.414])
    s0i = np_array([-0.1017, -0.0766, -0.0499, -0.0219, 0.0909])
    dij = np_array([
      0.0027,
      0.0085, 0.0017,
      0.0147, 0.0049, 0.0009,
      0.0393, 0.0219, 0.0117, 0.0062,
    ])
    pr = pr78(Pci, Tci, wi, mwi, dij, s0i)
    T0 = 0. + 273.15
    Tmin = -80. + 273.15
    Tmax = 150 + 273.15
    Pmax = 20e6
    maxpoints = 118
    env = env2p.runPT(pr, yi, 0., T0,
                      maxpoints=maxpoints, Pmax=Pmax, Tmin=Tmin, Tmax=Tmax)
    if plotting:
      self.plot(env, Tmin, Tmax, 0., Pmax)
    self.assertTrue(env.P.shape[0] == maxpoints)
    pass

